solution.solution.py:
import sqlite3


def create(con):
    con.execute("CREATE TABLE products (name TEXT NOT NULL UNIQUE, price REAL NOT NULL)")


def add(con, name, price):
    con.execute("INSERT INTO products (name, price) VALUES (?, ?)", (name, price))
    con.commit()


def cheapest(con, n):
    rows = con.execute("SELECT name FROM products ORDER BY price, name LIMIT ?", (n,))
    return [name for (name,) in rows]

unitTests:
import sqlite3

def fresh():
    con = sqlite3.connect(":memory:")
    create(con)
    return con

@test("cheapest first, ties by name")
def _():
    con = fresh()
    for name, price in [("tea", 2.5), ("coffee", 6.0), ("milk", 1.2), ("cocoa", 2.5)]:
        add(con, name, price)
    check_eq(cheapest(con, 3), ["milk", "cocoa", "tea"])

@test("quotes in names work")
def _():
    con = fresh()
    add(con, "Jo's tea", 3.0)
    check_eq(cheapest(con, 1), ["Jo's tea"])

@test("duplicate names are refused by the table")
def _():
    con = fresh()
    add(con, "tea", 1)
    check_raises(sqlite3.IntegrityError, add, con, "tea", 2)

@test("asking for more than there are")
def _():
    con = fresh()
    add(con, "tea", 1)
    check_eq(cheapest(con, 10), ["tea"])

